const specKeys=new Set(['feet','inches','ounces','pack','apparel-size','clothing-size','shoe-width','named-shade','color-code','full-flavor','style-code','pattern','two-dimensions','three-dimensions','waist-inseam','gb-capacity','ingredient-pair','zodiac-pattern','catalog-pattern','coordinated-color','noun-count','suffix-code','adjective-flavor']);
function rows(raw){const c=raw.split('Available Actions:')[0].split('[SEP]').map(t=>t.trim());const out=[];for(let i=0;i<c.length-2;i++)if(/^[A-Z0-9]{10}$/.test(c[i]))out.push({id:norm(c[i]),title:c[i+1],price:Number(c[i+2].match(/\$([\d.]+)/)?.[1]||NaN)});return out;}
