 return [...new Set(numberText(cleanTask(task)).replace(/coaxial/g,'coax').replace(/[^a-z]+/g,' ').split(/\s+/).filter(w=>w.length>2&&!ignored.has(w)).map(w=>w.length>4&&w.endsWith('s')?w.slice(0,-1):w))];
