   if(!choices.length)return 'Full size/width ledger for '+req.label+': '+(widthOffered.length?'separate actual width choices '+widthOffered.map(x=>x.group+' '+JSON.stringify(x.value)+(x.done?' SELECTED':' pending')).join('; ')+'; select size '+req.size+' independently if offered.':fixed?'the literal width wording is present in the actual title/read detail; confirm its intended meaning and select the actual size '+req.size+' separately.':'No actual complete size-and-width value or separate width choice is established. Plain '+req.size+' does not by itself confirm '+req.fit+'; inspect width evidence once or another product.')+' Real clicked fields '+JSON.stringify(f.product.selected)+'.';
