function literalNumericChoices(product,instruction){const req=requirement('clothing-size',instruction);if(!req||req.fit)return [];return product.groups.filter(g=>/size/.test(g.label)).flatMap(g=>g.values.filter(v=>form(v)===String(req.size)).map(value=>({group:g.label,value,selected:product.selected[g.label]===value})));}
